-- Generated final client-intake seed for local development and preview environments.
-- Production credentials and provider identifiers are intentionally excluded.
begin;



update public.service_categories set active=false where business_id=(select id from public.businesses where slug='luxury-barber-lounge') and slug not in ('haircuts-fades','beard-shaves','specialty');

update public.services set active=false,bookable=false,content_status='archived' where business_id=(select id from public.businesses where slug='luxury-barber-lounge') and slug not in ('haircut','skin-fade','beard','cut-and-beard','hot-towel-shave','kids-haircut','senior-haircut','line-up','design');

create table if not exists public.barber_profile_settings (barber_profile_id uuid primary key references public.barber_profiles(id) on delete cascade,years_cutting text,walk_ins boolean not null default true,photo_provided boolean not null default false,working_days jsonb not null default '{}'::jsonb,instagram_handle text,instagram_status text not null default 'not_provided' check (instagram_status in ('active','pending_confirmation','not_provided')),intake_notes jsonb not null default '{}'::jsonb,updated_at timestamptz not null default timezone('utc',now()));

update public.barber_profiles set active=false,featured=false where business_id=(select id from public.businesses where slug='luxury-barber-lounge') and slug not in ('angelica-aquino','hommy-rivera','barber-los','jose','elvis','alfredo-hernandez-pollo','russ-hawkins','daniel-penalo');

update public.barber_profile_services set active=false where barber_profile_id in (select id from public.barber_profiles where business_id=(select id from public.businesses where slug='luxury-barber-lounge'));



update public.barber_schedules set active=false,effective_to=current_date where barber_profile_id in (select id from public.barber_profiles where business_id=(select id from public.businesses where slug='luxury-barber-lounge')) and active=true;


update public.membership_plans set active=false,featured=false,status='archived' where business_id=(select id from public.businesses where slug='luxury-barber-lounge') and slug not in ('annual-52-week','monthly-4-week');

delete from public.packages where business_id=(select id from public.businesses where slug='luxury-barber-lounge') and not exists (select 1 from public.package_redemptions r where r.package_id=public.packages.id);




commit;
